-- Owner's legitimacy confirmation, not an AI-method confirmation. Keep older research as history.
UPDATE organizations SET triage_notes='Owner clarification (Sinan, 2026-10-14): this is a legitimate aviation organization. AI methods and deployments remain open; retain as needs_review pending profiling. Earlier notes below may question legitimacy and are historical. | ' || COALESCE(triage_notes,''), updated_at=datetime('now') WHERE id IN ('atac','flightkeys','airbus-defence-and-space') AND instr(COALESCE(triage_notes,''),'Owner clarification (Sinan, 2026-10-14)')=0;
INSERT INTO change_log(entity_type,entity_id,change_type,summary,agent) SELECT 'organization',id,'updated','Owner confirms organization legitimacy, not AI relevance. Historical triage notes retained.','orchestrator' FROM organizations WHERE id IN ('atac','flightkeys','airbus-defence-and-space');
